def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            return -q
        return q

    def parse_expr():
        v = parse_term()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return v
            op = s[i]
            i += 1
            r = parse_term()
            if v == "error" or r == "error":
                v = "error"
            elif op == "+":
                v = v + r
            else:
                v = v - r

    def parse_term():
        v = parse_unary()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return v
            op = s[i]
            i += 1
            r = parse_unary()
            if v == "error" or r == "error":
                v = "error"
            elif op != "*" and r == 0:
                v = "error"
            elif op == "*":
                v = v * r
            elif op == "/":
                v = trunc_div(v, r)
            else:
                v = v - r * trunc_div(v, r)

    def parse_unary():
        skip()
        if i < n and s[i] == "-":
            i += 1
            v = parse_unary()
            if v == "error":
                return "error"
            return -v
        return parse_power()

    def parse_power():
        v = parse_primary()
        skip()
        if i >= n or s[i] != "^":
            return v
        i += 1
        r = parse_unary()
        if v == "error" or r == "error" or r < 0:
            return "error"
        return v ** r

    def parse_primary():
        skip()
        if s[i] == "(":
            i += 1
            v = parse_expr()
            skip()
            i += 1
            return v
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    return parse_expr()
